UPDATE server_monitor_task
name = #{name}, server_id = #{serverId}, template_id = #{templateId}, collect_script = #{collectScript}, params = #{params}, threshold_rule = #{thresholdRule}, cron_expression = #{cronExpression}, alarm_channels = #{alarmChannels}, alarm_template_id = #{alarmTemplateId}, is_active = #{isActive}, update_time = NOW()
